update public.learning_paths
set
  title = 'Introduction to Hispanic Literature',
  goal = 'Introduction to Hispanic Literature',
  summary = 'This course introduces students to the formal study of Hispanic literature across Spain, Latin America, the Caribbean, and U.S. Latinx contexts. Students learn to read poetry, narrative, drama, essay, chronicle, testimony, and hybrid forms in Spanish while connecting close textual analysis to historical period, genre, canon formation, identity, and critical method. The course is designed as a bridge between advanced language work and upper-division seminars. Its main goal is to help students write precise, evidence-based literary arguments in Spanish while developing the vocabulary and intellectual habits needed for serious work in Hispanic literary studies.',
  data = $ihisjson${"slug": "introduction-to-hispanic-literature", "title": "Introduction to Hispanic Literature", "description": "This course introduces students to the formal study of Hispanic literature across Spain, Latin America, the Caribbean, and U.S. Latinx contexts. Students learn to read poetry, narrative, drama, essay, chronicle, testimony, and hybrid forms in Spanish while connecting close textual analysis to historical period, genre, canon formation, identity, and critical method. The course is designed as a bridge between advanced language work and upper-division seminars. Its main goal is to help students write precise, evidence-based literary arguments in Spanish while developing the vocabulary and intellectual habits needed for serious work in Hispanic literary studies.", "topics": [{"id": "4f17fc42-6870-458e-8982-c219d347653b", "type": "topic", "title": "Genres and Literary Terminology", "description": "Students build the shared vocabulary needed to read Hispanic literature as literature: genre, form, voice, image, structure, and historical convention.", "children": [{"id": "a49ab25a-73a6-4e85-aebf-cca6f28cd42b", "type": "subtopic", "title": "Major literary genres", "children": [{"id": "8f838097-40e4-45f2-9b0a-019943162239", "type": "concept", "title": "Poetry and lyric speaker"}, {"id": "f67ede0e-726b-4ed4-bfae-bbcceeae31a4", "type": "concept", "title": "Short story and novel"}, {"id": "be9a3b9f-d164-4e2f-9cac-e28b90344b05", "type": "concept", "title": "Drama and performance text"}, {"id": "60a957af-c851-4be1-b0c9-7d1172e2baa9", "type": "concept", "title": "Essay, chronicle, testimony, and crónica"}], "description": "This subtopic clarifies how poetry, narrative, drama, essay, chronicle, testimony, and hybrid forms create meaning differently."}, {"id": "70f50466-0361-41e9-ab8e-0acddb4740d9", "type": "subtopic", "title": "Core critical vocabulary", "children": [{"id": "9d29ebb7-d4fb-44f0-9138-bf71cfd67fbf", "type": "concept", "title": "Image, symbol, motif, and theme"}, {"id": "a5d2617a-7107-4764-9dd7-a5ca9b68b77b", "type": "concept", "title": "Tone, irony, ambiguity, and paradox"}, {"id": "2f44cba7-4b89-4ba9-9340-0abab9e1b623", "type": "concept", "title": "Form, structure, stanza, scene, and plot"}], "description": "Students learn the terms that make precise discussion possible rather than relying on impressionistic reactions."}, {"id": "139a237c-04fd-4818-8996-10b6de61af5d", "type": "subtopic", "title": "Spanish-language literary metalanguage", "children": [{"id": "8e936c49-caab-4721-93f7-1dd45c18e943", "type": "concept", "title": "Voz narrativa"}, {"id": "9ac3e678-7d41-4c72-bfec-0dc476c5ef11", "type": "concept", "title": "Hablante lírico"}, {"id": "cddf0b3c-4a71-4fa1-96e8-ce901d15bfa6", "type": "concept", "title": "Verso, estrofa, rima, and ritmo"}, {"id": "a88bbdbc-4084-4e6d-abe8-8cd745bc71f0", "type": "concept", "title": "Trama, personaje, and desenlace"}], "description": "The course moves students toward discussing texts in Spanish with disciplinary fluency."}]}, {"id": "c4270b61-1245-4be1-854c-22168b3d9f02", "type": "topic", "title": "Close Reading in Spanish", "description": "Close reading trains students to slow down, notice language, and connect textual details to interpretation in Spanish.", "children": [{"id": "ebb8ed95-3778-46f1-9f7e-25b0408149dd", "type": "subtopic", "title": "Annotation as method", "children": [{"id": "6abd8bd3-355d-44ef-924f-8ca38ef098b3", "type": "concept", "title": "Diction and repeated language"}, {"id": "09dc5745-0f6a-4972-8b66-1f34b1bcf729", "type": "concept", "title": "Syntax and sentence rhythm"}, {"id": "304037a2-8518-411e-b35f-5a83db504070", "type": "concept", "title": "Shifts in tense, address, and perspective"}], "description": "Students practice marking patterns and questions so interpretation begins in evidence."}, {"id": "3f7f33c1-30a7-4282-abcd-c6a0b0ece723", "type": "subtopic", "title": "From observation to claim", "children": [{"id": "a8228800-9d2e-493c-98cf-cba4003dc962", "type": "concept", "title": "Textual evidence"}, {"id": "9d128eb8-1661-4859-97b2-b668082f871a", "type": "concept", "title": "Interpretive stakes"}, {"id": "5f6eb0c0-27a3-4a4c-9caa-4f0051f48943", "type": "concept", "title": "Claim, reason, evidence, and warrant"}], "description": "This subtopic helps students convert textual noticing into arguable literary analysis."}, {"id": "8188b17f-9a1a-4f17-8468-a0f00c1190ab", "type": "subtopic", "title": "Reading across difficulty", "children": [{"id": "b6c0130c-8524-4502-9071-6d2586d0432f", "type": "concept", "title": "Context clues"}, {"id": "4f654a3e-b75b-46e9-8ca7-57b778b3c33a", "type": "concept", "title": "Strategic dictionary use"}, {"id": "54248409-2468-4a41-ab22-9b3f170a88cc", "type": "concept", "title": "Archaisms, regionalisms, and register"}], "description": "Students learn strategies for older, regional, experimental, or lexically dense Spanish."}]}, {"id": "7b08b7bb-5b24-4fa9-a9ca-7a31b13720ad", "type": "topic", "title": "Poetry, Meter, and Sound", "description": "Poetry foregrounds language itself; students learn how rhythm, sound, and compression shape meaning across Hispanic traditions.", "children": [{"id": "3011c053-7de4-47bc-8be7-150157ab4cda", "type": "subtopic", "title": "Poetic form and meter", "children": [{"id": "c26df557-85e1-4cd2-b375-c9afe9fb7b17", "type": "concept", "title": "Syllable counting and sinalefa"}, {"id": "a0f86953-0d72-45be-8bd5-76f9076f4a50", "type": "concept", "title": "Romance, sonnet, décima, and free verse"}, {"id": "5167b9db-4455-4e99-88cf-112bd28758dd", "type": "concept", "title": "Rhyme, assonance, and consonance"}], "description": "Students learn basic scansion and form so they can connect sound pattern to interpretation."}, {"id": "31550d80-ab39-4283-8c4f-1fee85f37700", "type": "subtopic", "title": "Figurative language", "children": [{"id": "63e2efa1-5340-4910-b467-2f31aa84c539", "type": "concept", "title": "Metaphor and simile"}, {"id": "fef2b4a3-926e-405a-8861-05d267e4f961", "type": "concept", "title": "Personification and apostrophe"}, {"id": "43c6b93d-8f47-48f7-ad88-fbbe9905a147", "type": "concept", "title": "Symbol, allegory, and conceit"}], "description": "This subtopic focuses on how poems make arguments through images and associations."}, {"id": "e5fe890b-7179-4c1a-bb15-e84060fb9cc5", "type": "subtopic", "title": "Performance and voice", "children": [{"id": "60fb4bc2-b81c-4e2a-a27d-98a4cb11e7b0", "type": "concept", "title": "Recitation"}, {"id": "5e059cae-892b-4564-9cf8-2d655b3a059f", "type": "concept", "title": "Orality and song"}, {"id": "12f6ec2a-e05b-478f-b028-99192b0e950e", "type": "concept", "title": "Public poetry and political voice"}], "description": "Students consider poetry as spoken, recited, sung, and embodied language."}]}, {"id": "40740260-3067-4e2d-b99c-ca25c55f9e92", "type": "topic", "title": "Narrative Voice and Point of View", "description": "Narrative analysis teaches students how stories organize experience, authority, memory, time, and perception.", "children": [{"id": "b8d8dd6a-8798-4840-b96b-0640f89f2fee", "type": "subtopic", "title": "Narrators and focalization", "children": [{"id": "d45b02cf-7508-4919-b5ff-44dd723c0fe9", "type": "concept", "title": "First, second, and third person"}, {"id": "785d3ee5-a25f-4295-9dbd-6f3507fda3ee", "type": "concept", "title": "Reliable and unreliable narration"}, {"id": "c49f154e-76c9-4a91-8f4c-207a0a3eac7d", "type": "concept", "title": "Focalization and distance"}], "description": "Students distinguish who speaks from who sees, and why that distinction matters."}, {"id": "5e0a427e-83c2-4921-8846-d2e8bb88242f", "type": "subtopic", "title": "Time and structure", "children": [{"id": "5f61cb50-e650-42f8-8288-4070668e05e5", "type": "concept", "title": "Chronology and anachrony"}, {"id": "52a88bbd-ff49-416e-a698-5ae39c9e3b9d", "type": "concept", "title": "Flashback and foreshadowing"}, {"id": "2703d5ff-072e-436c-96d1-d293b5fad552", "type": "concept", "title": "Frame narratives and fragmentation"}], "description": "This subtopic explains how order, pacing, and repetition make narrative meaning."}, {"id": "c8aa4ccb-f66e-4a5a-9619-950f0db68d45", "type": "subtopic", "title": "Short fiction and the novel", "children": [{"id": "c99bf280-199e-4830-8ea7-70f5b70b2ca4", "type": "concept", "title": "Opening and closure"}, {"id": "2153017c-b6fa-4141-888c-360fe3232625", "type": "concept", "title": "Conflict and characterization"}, {"id": "5cfaf431-1e8b-4493-8204-f9fb8af18e1b", "type": "concept", "title": "Space, setting, and social world"}], "description": "Students compare concentrated narrative techniques with longer forms of world-building and character development."}]}, {"id": "86b29106-4a14-4ebf-8b07-6fc7f64739f9", "type": "topic", "title": "Drama and Performance", "description": "Drama asks students to read text as action: speech, staging, gesture, audience, and embodied conflict.", "children": [{"id": "244a9277-ef28-4ff8-9ce7-dccc5b4f0fb7", "type": "subtopic", "title": "Reading plays as performance", "children": [{"id": "c79deb92-bd24-4dfa-9ff8-b5cb96c95f7e", "type": "concept", "title": "Scenes and acts"}, {"id": "f5ff29ac-5372-4a1f-bacc-f475fd5c1e33", "type": "concept", "title": "Blocking and gesture"}, {"id": "527df1e4-2cd7-4e4c-a294-345a23582448", "type": "concept", "title": "Props, costume, and sound"}], "description": "Students learn to interpret stage directions, dialogue, silence, and theatrical space."}, {"id": "fbdf2803-5768-4d68-a576-cd723fe4ca3c", "type": "subtopic", "title": "Classical and modern dramatic traditions", "children": [{"id": "e0ff4a75-5aae-405c-82cf-2c6f833c002d", "type": "concept", "title": "Comedia and honor drama"}, {"id": "eb415fff-a39d-4d7c-bc28-ca07d0e3775f", "type": "concept", "title": "Modern realism and experimental theater"}, {"id": "6bce0933-51cb-48f8-af0b-d80011098292", "type": "concept", "title": "Political theater and performance art"}], "description": "This subtopic connects major Spanish-language theatrical forms to historical audiences."}, {"id": "60060620-297c-4048-b8f7-9792a80f9e46", "type": "subtopic", "title": "Adaptation and staging choices", "children": [{"id": "23923f63-8b1c-4f6d-8f23-5719b89d69f2", "type": "concept", "title": "Casting and embodiment"}, {"id": "cb33fd2d-4857-475f-ac82-0bcf0a55abfe", "type": "concept", "title": "Translation for performance"}, {"id": "dd0f495d-7e85-431b-8407-470b20d7b3b3", "type": "concept", "title": "Audience, censorship, and reception"}], "description": "Students test interpretation by imagining how performance choices change meaning."}]}, {"id": "ba2f64bf-914d-47df-92ae-5758105fed52", "type": "topic", "title": "Historical Periods and Movements", "description": "A world-class introduction needs literary history: students situate texts within major Hispanic periods without reducing literature to background.", "children": [{"id": "23265c0b-d97e-4e49-9db4-f54dc0238aa8", "type": "subtopic", "title": "Medieval and early modern foundations", "children": [{"id": "856db53b-e4ab-47d5-8251-76cd8bd92fbb", "type": "concept", "title": "Epic, lyric, and romance traditions"}, {"id": "237aeabf-77e4-4a41-836c-a64ea5f7d7cd", "type": "concept", "title": "Golden Age theater and prose"}, {"id": "dcb237af-8938-41e2-8ec1-724b2db38067", "type": "concept", "title": "Conquest chronicles and colonial letters"}], "description": "Students encounter the formation of Iberian literary traditions and early transatlantic writing."}, {"id": "b36792ea-1fd6-43e7-af7a-d633297b8891", "type": "subtopic", "title": "Modernity and the nineteenth century", "children": [{"id": "49ba97a5-b672-4e82-ab39-f427d3d0130e", "type": "concept", "title": "Romanticism and realism"}, {"id": "d22ae002-63a6-426b-b144-d443a26fd429", "type": "concept", "title": "Costumbrismo"}, {"id": "ba605d0c-0b6f-4120-a322-41ff5266d535", "type": "concept", "title": "Nation-building and independence-era writing"}], "description": "This subtopic connects nation, liberalism, race, gender, empire, and print culture."}, {"id": "d8c5d560-fa15-4244-bac5-96477a447ff1", "type": "subtopic", "title": "Twentieth and twenty-first century movements", "children": [{"id": "a2d01228-5e3c-4adf-bf6a-2ed2003a7db2", "type": "concept", "title": "Modernismo and vanguardias"}, {"id": "f754b152-470b-40fb-88a5-11c97b76619d", "type": "concept", "title": "Boom and post-boom narrative"}, {"id": "593f34ad-81ad-4fb3-90e7-f2f4391f84b6", "type": "concept", "title": "Contemporary, diasporic, and border writing"}], "description": "Students learn how modernismo, avant-garde, boom, post-boom, dictatorship, diaspora, and digital culture reshape literary form."}]}, {"id": "107e9a06-3bc8-40ae-9101-cb08cd504e29", "type": "topic", "title": "Colonial, Transatlantic, and Hemispheric Contexts", "description": "This section places Hispanic literature in motion across Spain, Latin America, the Caribbean, Africa, Indigenous worlds, and the United States.", "children": [{"id": "9bff0d28-9ae2-445f-accd-4dbcb86c41b5", "type": "subtopic", "title": "Colonial encounter and its archives", "children": [{"id": "5735fdf9-79e4-4073-bd04-3ee3d86eb4a4", "type": "concept", "title": "Chronicles and letters"}, {"id": "652ed625-5279-4153-a555-8d5411641c9d", "type": "concept", "title": "Conversion, empire, and violence"}, {"id": "de61e304-af7e-445a-bf9d-49c5c0fd9a9e", "type": "concept", "title": "Indigenous and mestizo textualities"}], "description": "Students learn to read colonial texts critically as literary, political, theological, and archival documents."}, {"id": "3143df98-bd0a-4252-a87f-fb595227e774", "type": "subtopic", "title": "Transatlantic circulation", "children": [{"id": "7f5453ff-017c-4a50-a629-3946ec819b17", "type": "concept", "title": "Print culture and censorship"}, {"id": "a367d2b3-3a65-4c1c-9300-83aa3be8dfe7", "type": "concept", "title": "Exile and migration"}, {"id": "18e4940a-f410-4c7f-81b4-5269b4427408", "type": "concept", "title": "Translation and reception"}], "description": "This subtopic follows books, people, genres, and ideas across oceans and empires."}, {"id": "99d4ef01-5ef8-498e-80c0-1dcd9f4eaf98", "type": "subtopic", "title": "Hemispheric and Latinx frames", "children": [{"id": "4a96fdee-c044-4b9f-af75-395c75fced19", "type": "concept", "title": "Borderlands"}, {"id": "5c940ccb-b4dc-4b44-a6ed-fe783cb6b3f6", "type": "concept", "title": "Diaspora and bilingualism"}, {"id": "b3459d10-bc5c-477a-ba83-71ae7cb93ee5", "type": "concept", "title": "Memory, citizenship, and belonging"}], "description": "Students examine how U.S. Hispanic and Latinx writing converses with Latin American and Iberian traditions."}]}, {"id": "66ea54b6-e00a-47e0-a9b5-570e73e38175", "type": "topic", "title": "Canon, Identity, and Representation", "description": "Students examine who gets read, who gets excluded, and how literature stages identity, power, and community.", "children": [{"id": "f7fe47a3-b9e1-4b54-9021-f97ad0f04e55", "type": "subtopic", "title": "Canon formation", "children": [{"id": "4b074dd0-3ca2-48b9-b747-4fd281ae45f9", "type": "concept", "title": "Anthologies and national traditions"}, {"id": "419dfda9-d4b5-488b-a201-9c7c5cfcbd9b", "type": "concept", "title": "Major authors and counter-canons"}, {"id": "0d580248-bc37-40ac-a251-21f4ae24ed15", "type": "concept", "title": "Awards, publishing, and the classroom"}], "description": "This subtopic asks how syllabi, anthologies, institutions, and criticism shape literary value."}, {"id": "09079d7f-0531-4761-bb3f-d94cb3677f00", "type": "subtopic", "title": "Race, ethnicity, gender, and sexuality", "children": [{"id": "a2fd0bb5-c826-4580-bb6e-8aa2af1ba9f1", "type": "concept", "title": "Indigeneity and Afro-Hispanic writing"}, {"id": "755e2c31-f0d5-4048-b81e-94228dcb4800", "type": "concept", "title": "Feminist and queer readings"}, {"id": "c613e8ce-b78e-48b1-806f-93296548dad6", "type": "concept", "title": "Class, labor, and social hierarchy"}], "description": "Students learn to analyze representation without flattening texts into simple social messages."}, {"id": "5a158a90-5f76-4780-9b05-b5011f11503a", "type": "subtopic", "title": "Ethics of interpretation", "children": [{"id": "1283405e-516d-4775-ac59-42d628129996", "type": "concept", "title": "Contextualization"}, {"id": "1585d0b5-7c66-40e5-9f51-01056d618d0a", "type": "concept", "title": "Stereotype and resistance"}, {"id": "724ef200-64a2-4089-bdcb-00b8ab74d88d", "type": "concept", "title": "Reader position and interpretive humility"}], "description": "Students consider how to discuss difficult texts, historical violence, and cultural difference responsibly."}]}, {"id": "4c5e4af5-8d52-441f-a2d3-76540497e542", "type": "topic", "title": "Literary Theory and Critical Methods", "description": "This topic gives students a foundation in methods used by strong Spanish departments and prepares them for upper-division seminars.", "children": [{"id": "6984ebe5-fdf1-44fd-86db-fe5c323117e7", "type": "subtopic", "title": "Foundational critical lenses", "children": [{"id": "aaa9bcec-746d-4e06-a6d2-c56b0a358fdb", "type": "concept", "title": "Formalism"}, {"id": "241c0d32-6141-47b8-b798-58e9cf64e25e", "type": "concept", "title": "Historical and cultural studies"}, {"id": "56866ab8-64c2-40d4-9a93-f65f6b05faa5", "type": "concept", "title": "Postcolonial and decolonial approaches"}], "description": "Students see how different methods ask different questions of the same text."}, {"id": "847f3601-5e53-4cbd-a305-2510cf46aced", "type": "subtopic", "title": "Gender, race, and ideology", "children": [{"id": "3589bdea-f6ab-4c26-92fb-c1bf3a38fd5a", "type": "concept", "title": "Feminist criticism"}, {"id": "46f698d6-602c-4208-bb43-2709f871cd2d", "type": "concept", "title": "Critical race and Afro-diasporic approaches"}, {"id": "90f104ce-b619-498a-83c1-05213a5e53c2", "type": "concept", "title": "Marxist and materialist reading"}], "description": "This subtopic introduces lenses that foreground power, identity, and representation."}, {"id": "92523d5d-1757-453b-9f9d-89978e869baa", "type": "subtopic", "title": "Method as argument", "children": [{"id": "7f6da3a9-6a99-4fb3-8aa1-34f6280245d6", "type": "concept", "title": "Research question design"}, {"id": "2e10ea0f-deb2-414e-986b-a37f97e758f0", "type": "concept", "title": "Method-language in thesis statements"}, {"id": "41425bd9-e8e3-4d5c-aaf4-54601b06ffe7", "type": "concept", "title": "Limits of a critical lens"}], "description": "Students practice naming the interpretive method behind their claims."}]}, {"id": "dd7f723d-0363-4a88-8529-9102a85c9abe", "type": "topic", "title": "Research, Citation, and Literary Argument", "description": "Research and citation teach students to join scholarly conversations with evidence, precision, and academic integrity.", "children": [{"id": "994a23ca-3103-45f6-be94-7992047c38f9", "type": "subtopic", "title": "Finding scholarly sources", "children": [{"id": "da4aabe1-1f6f-47f5-91d0-a7c61af84a5f", "type": "concept", "title": "Library catalogs and databases"}, {"id": "5013785f-a31c-4fa6-a50c-ca503e32142a", "type": "concept", "title": "Peer-reviewed criticism"}, {"id": "cd2a9ff7-10ef-4879-8d0d-666a57a2fe32", "type": "concept", "title": "Digital archives and primary sources"}], "description": "Students distinguish primary texts, scholarly articles, reference works, and web resources."}, {"id": "319e7362-1041-49bc-be0a-ddcc41f40b4c", "type": "subtopic", "title": "Citation and documentation", "children": [{"id": "6a396e86-5f64-46b5-9904-3cea371f952b", "type": "concept", "title": "MLA in-text citation"}, {"id": "52d25968-fef2-442b-bab0-c1f262aa0990", "type": "concept", "title": "Works cited pages"}, {"id": "034b0ff5-c931-49b9-b242-edb3f87ce059", "type": "concept", "title": "Quoting, paraphrasing, and integrating Spanish"}], "description": "This subtopic builds responsible use of sources in MLA-style literary work."}, {"id": "a432208e-7958-40be-af04-b75cfcdeb9f7", "type": "subtopic", "title": "Building a literary argument", "children": [{"id": "9